__NUXT_JSONP__("/anticorrupcion/noticias/el_sistema_nacional_anticorrupcion_la_nueva_alerta_contra_un_organismo_autonomo", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C){return {data:[{post:{slug:"el_sistema_nacional_anticorrupcion_la_nueva_alerta_contra_un_organismo_autonomo",title:"El Sistema Nacional Anticorrupción: la nueva alerta contra un organismo autónomo",date:"2023-04-25T15:24:41.464Z",img:"https:\u002F\u002Fucarecdn.com\u002F9bc1f024-0014-4f4c-994d-b7f4450488f5\u002F","img-alt":"Sistema Nacional Anticorrupción",autor:"Dulce Soto, Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2023\u002F04\u002F25\u002Fsistema-nacional-anticorrupcion-organismo-autonomo",category:"anticorrupcion",extracto:"Siete años después de su creación, cinco estados no han cumplido con la obligación de diseñar una Política Anticorrupción y únicamente 12 cuentan con un Programa de Implementación de esa política.",toc:[{id:r,depth:g,text:s},{id:t,depth:g,text:u},{id:v,depth:g,text:w},{id:x,depth:g,text:y},{id:z,depth:g,text:A},{id:B,depth:g,text:C}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Aunque la principal bandera en el discurso del presidente "},{type:b,tag:e,props:{},children:[{type:a,value:"Andrés Manuel López Obrador"}]},{type:a,value:" ha sido la lucha contra la corrupción, en los hechos ha impulsado acciones que obstaculizan el combate a estos actos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El Ejecutivo federal va ahora por "},{type:b,tag:f,props:{href:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2023\u002F04\u002F24\u002Fintegrantes-del-sistema-anticorrupcion-defienden-la-secretaria-y-piden-dialogo",rel:[n,o,p],target:q},children:[{type:a,value:"desaparecer la Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA)"}]},{type:a,value:" para que la Secretaría de la Función Pública (SFP) asuma sus funciones. Sin embargo, "},{type:b,tag:e,props:{},children:[{type:a,value:"esto pondría en riesgo la autonomía y operación de este aparato"}]},{type:a,value:", alertan expertos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Con esta intención, el mandatario continúa su embestida contra los organismos autónomos, pues a lo largo de su gobierno se ha dedicado a "},{type:b,tag:e,props:{},children:[{type:a,value:"estigmatizar y criticar a las instituciones con funciones de transparencia y rendición de cuentas"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Ese sistema se creó en plena corrupción para simular que se iba a combatir la corrupción. No se necesita esa aparato. ¿Saben para qué se utilizó ese aparato? Para ocultar la información\", ha declarado el presidente sobre el SNA."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para los analistas, el desdén por los órganos autónomos de López Obrador, quien ahora envió "},{type:b,tag:f,props:{href:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2023\u002F04\u002F18\u002Famlo-busca-fusionar-18-instituciones-publicas-con-otras-dependencias-de-gobierno",rel:[n,o,p],target:q},children:[{type:a,value:"una iniciativa a la Cámara de Diputados para \"fusionar\" 18 organismos y dependencias"}]},{type:a,value:" —entre ellas la Secretaría Ejecutiva del SNA—, alienta la opacidad."}]},{type:a,value:c},{type:b,tag:h,props:{id:r},children:[{type:b,tag:f,props:{href:"#sistema-anticorrupci%C3%B3n-en-la-mira-de-amlo",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:a,value:s}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Especialistas consideran que la propuesta de desaparecer la Secretaría Ejecutiva del SNA busca, en los hechos, desarmar toda la plataforma, como sucede actualmente con el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos personales (INAI)."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En la últimas semanas, se dio a conocer un audio del secretario de Gobernación, Adán Augusto López, explicando que para el presidente López Obrador, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2023\u002F04\u002F14\u002Faudio-de-adan-augusto-revela-que-amlo-busco-dejar-inoperante-al-inai?utm_source=internal&utm_medium=branded",rel:[n,o,p],target:q},children:[{type:a,value:"el \"mundo ideal\" es que no se nombre a los comisionados que hacen falta para que el INAI se quede inoperante"}]},{type:a,value:" , debido a que la ley no le permite sesionar con solo cuatro integrantes."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Integrantes del SNA han alertado que la iniciativa del Ejecutivo se pretende votar esta semana \"sin discusión ni objeción\" y solicitado al Congreso organizar primero mesas de análisis sobre la importancia del organismo."}]},{type:a,value:c},{type:b,tag:h,props:{id:t},children:[{type:b,tag:f,props:{href:"#el-impacto-de-la-desaparici%C3%B3n",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:u}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Si se concreta la desaparición de la SESNA, "},{type:b,tag:e,props:{},children:[{type:a,value:"la lucha contra la corrupción quedaría en manos del gobierno federal"}]},{type:a,value:", sin autonomía del Poder Ejecutivo."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“La agenda anticorrupción básicamente será una agenda que decida el presidente y no necesariamente una agenda de lo que se requiere hacer en el combate a la corrupción”, explica Dalia Toledo, directora de Finanzas Públicas y Anticorrupción de Ethos, Laboratorio de Políticas Públicas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La muestra de que el SNA es necesario, incluso con sus debilidades, es que en el actual gobierno como en el anterior se han impulsado acciones para obstaculizarlo. En el sexenio del priista Enrique Peña Nieto, por ejemplo, "},{type:b,tag:e,props:{},children:[{type:a,value:"evitaron nombrar magistrados anticorrupción, redujeron el presupuesto de la fiscalía anticorrupción"}]},{type:a,value:" "},{type:b,tag:e,props:{},children:[{type:a,value:"y no abordaron el caso Odebrecht en el pleno del INAI,"}]},{type:a,value:" entre otras acciones menos visibles, explica Eduardo Bohórquez, director ejecutivo de Transparencia Mexicana."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En la administración de López Obrador tampoco se ha fortalecido el SNA. Por el contrario, se desplazó su estrategia anticorrupción, en un inicio a la Unidad de Inteligencia Financiera y luego a la Fiscalía General de la República. Aunque esta dependencia es autónoma, subraya el experto, su titular es nombrado por el presidente."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sin la Secretaría Ejecutiva, se perdería el seguimiento imparcial a la Política Nacional Anticorrupción; la interacción con el Comité de Participación Ciudadana y no operaría la Plataforma Digital Nacional, donde se concentran las declaraciones patrimoniales de las y los servidores públicos. También "},{type:b,tag:e,props:{},children:[{type:a,value:"se pondría en riesgo la transparencia de las compras públicas."}]}]},{type:a,value:c},{type:b,tag:h,props:{id:v},children:[{type:b,tag:f,props:{href:"#concentrar-el-poder",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:a,value:w}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La propuesta del presidente traería impactos severos en el combate a la corrupción, pues degrada un sistema de Estado —que opera con representación de los tres poderes y la ciudadanía—, a una dependencia de gobierno, explica Jorge Alberto Alatorre, presidente del Comité de Participación Ciudadana del SNA."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pese a ser un organismo pequeño, la SESNA es eficiente, pues concentra información de inteligencia anticorrupción para los tres poderes y órganos de gobierno y no depende de ninguno de ellos en lo individual."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"\"Desarticular o desaparecer organismos de control es un riesgo para el futuro de la democracia\", advierte el director de Transparencia Mexicana, Eduardo Bohórquez."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dejar sus funciones en manos de la SFP no garantiza un mejor resultado. Ya hay antecedentes de los sesgos con los que opera a la hora de investigar y sancionar casos relevantes de corrupción: la vara es distinta para los funcionarios de mediano nivel que para las personas \"políticamente conectadas\", subraya Alatorre."}]},{type:a,value:c},{type:b,tag:h,props:{id:x},children:[{type:b,tag:f,props:{href:"#el-olvido-de-los-sistemas-estatales-anticorrupci%C3%B3n",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:y}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Varios de "},{type:b,tag:e,props:{},children:[{type:a,value:"los sistemas anticorrupción de los estados están debilitados"}]},{type:a,value:", pero desaparecerlos en lugar de reforzarlos significaría un retroceso en el combate a la corrupción a nivel local. Estos sistemas son los encargados de prevenir, detectar y sancionar las faltas administrativas y los hechos de corrupción. Además de apoyar en la fiscalización y control de los recursos públicos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Desde su nacimiento en 2015, el SNA ha enfrentado resistencias. "},{type:b,tag:e,props:{},children:[{type:a,value:"Pasaron seis años para que las 32 entidades federativas integraran sus sistemas anticorrupción estatales."}]},{type:a,value:" Todavía en 2021, Baja California y Baja California Sur tenían pendiente la designación de sus fiscales anticorrupción."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Siete años después, cinco estados no han cumplido con la obligación de diseñar una Política Anticorrupción o no la tienen aprobada todavía. Se trata de la "},{type:b,tag:e,props:{},children:[{type:a,value:"Ciudad de México, Nuevo León, Tamaulipas, Baja California y Chihuahua"}]},{type:a,value:". Y únicamente 12 entidades federativas cuentan con un Programa de Implementación de su Política Anticorrupción. El retraso se debe, sobre todo, a la falta de voluntad política."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En este gobierno, el andamiaje anticorrupción ha quedado de lado. Dalia Toledo expone, por ejemplo, que aunque la ley establece criterios rigurosos para la designación de los integrantes del SNA, a esos cargos han llegado perfiles no idóneos. El Comité de Participación Ciudadana de Baja California, ejemplificó Toledo, hace meses operaba a cargo de urólogos, comerciantes e ingenieros, cuando lo necesario es un perfil especialista en transparencia, rendición de cuentas, acceso a la información y combate a la corrupción."}]},{type:a,value:c},{type:b,tag:h,props:{id:z},children:[{type:b,tag:f,props:{href:"#recursos-anticorrupci%C3%B3n",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:A}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A nivel federal, a la Secretaría Ejecutiva del Sistema Nacional Anticorrupción se le aprobó un "},{type:b,tag:e,props:{},children:[{type:a,value:"presupuesto para 2023 de 129,459 millones de pesos"}]},{type:a,value:". Aunque representa 5.1% más que en 2022, este monto abarca apenas el 1.9% de todo el gasto del Anexo Transversal Anticorrupción, según un informe del SNA."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Mientras que la Auditoría Superior de la Federación (ASF) recibe el 40.8% del presupuesto; el Consejo de la Judicatura Federal (CJF), 24.34% y la Secretaría de la Función Pública 18.36%."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pero los gobiernos estatales han sido renuentes a asignar mayores recursos a la lucha anticorrupción. El SNA ha buscado que todos los estados adopten un anexo así para informar cuánto dinero se invierte en el combate a la corrupción. A la fecha, "},{type:b,tag:e,props:{},children:[{type:a,value:"sólo cuatroestados cuentan con este instrumento: Jalisco, Nuevo León, Sinaloa y Quintana Roo."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Pese a estas debilidades, el país requiere que instituciones de este tipo continúen funcionando y mejorando para que sean un contrapeso a los poderes gubernamentales. “Por lo que no podemos permitir que pase esta iniciativa (de desaparecer la SESNA) y menos sin que exista un diálogo y acuerdos con la sociedad civil”, apunta Toledo."}]},{type:a,value:c},{type:b,tag:h,props:{id:B},children:[{type:b,tag:f,props:{href:"#los-resultados-anticorrupci%C3%B3n-de-amlo",ariaHidden:i,tabIndex:j},children:[{type:b,tag:k,props:{className:[l,m]},children:[]}]},{type:b,tag:e,props:{},children:[{type:a,value:C}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Aunque el presidente López Obrador ha asegurado en reiteradas ocasiones que en México ya no hay corrupción, la población no percibe esto. En 2020**, las personas de 15 años en adelante consideraron que la corrupción seguía siendo el principal problema del país.**"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con la Encuesta Nacional de Cultura Cívica del Inegi, 61.6% afirmó que durante este sexenio la corrupción había aumentado o se mantenía en altos niveles, como en la administración pasada."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Además, en este gobierno, el número de auditorías internas ha caído 50% desde 2020; las denuncias por irregularidades detectadas externamente se han reducido drásticamente y se han mantenido descabezadas instituciones responsables de combatir conductas irregulares de los servidores públicos, advierte el estudio "},{type:b,tag:"em",props:{},children:[{type:a,value:"¿Cómo se castiga la corrupción en México?"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Los cambios significativos en el combate a la corrupción sólo ocurrirán tras varios años de consolidación institucional y, por ello, es necesario defender el SNA, menciona Jorge Alberto Alatorre, presidente del Comité de Participación Ciudadana del Sistema Nacional Anticorrupción. \"Esto no podrá ocurrir si nos obcecamos en destruir o coptar espacios de interacción como nos ofrece el Sistema Nacional Anticorrupción\"."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A punto de terminar, el sexenio de López Obrador quedará a deber también en cuanto al combate a la corrupción. Su principal bandera quedará en el discurso."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fel_sistema_nacional_anticorrupcion_la_nueva_alerta_contra_un_organismo_autonomo",extension:".md",createdAt:"2023-06-19T05:12:02.359Z",updatedAt:"2023-05-30T23:46:33.654Z"}}],fetch:{},mutations:[]}}("text","element","\n","p","strong","a",2,"h2","true",-1,"span","icon","icon-link","nofollow","noopener","noreferrer","_blank","sistema-anticorrupción-en-la-mira-de-amlo","Sistema Anticorrupción, en la mira de AMLO","el-impacto-de-la-desaparición","El impacto de la desaparición","concentrar-el-poder","Concentrar el poder","el-olvido-de-los-sistemas-estatales-anticorrupción","El olvido de los sistemas estatales anticorrupción","recursos-anticorrupción","Recursos anticorrupción","los-resultados-anticorrupción-de-amlo","Los resultados anticorrupción de AMLO")));